class Solution {
  public int magicalString(int n) {
    if (n <= 3) return 1;
    int[] s = new int[n + 2];
    s[0] = 1;
    s[1] = 2;
    s[2] = 2;
    int head = 2, tail = 3, ones = 1, next = 1;
    // s[head] says how many copies of the next value to append
    while (tail < n) {
      for (int k = 0; k < s[head] && tail < n; k++) {
        s[tail++] = next;
        if (next == 1) ones++;
      }
      next = 3 - next;
      head++;
    }
    return ones;
  }
}
